ALTER TYPE "MediaAssetKind" ADD VALUE 'COMMUNITY_IMAGE';
CREATE TYPE "CommunityPostType" AS ENUM ('TEXT', 'IMAGE', 'POLL', 'VIDEO_SHARE');
CREATE TYPE "CommunityPostStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'PUBLISHED', 'HIDDEN', 'REMOVED');
CREATE TABLE "CommunityPost" ("id" UUID NOT NULL, "channelId" UUID NOT NULL, "authorAccountId" UUID NOT NULL, "type" "CommunityPostType" NOT NULL, "status" "CommunityPostStatus" NOT NULL DEFAULT 'DRAFT', "body" TEXT, "imageAssetId" UUID, "sharedVideoId" UUID, "scheduledPublishAt" TIMESTAMP(3), "publishedAt" TIMESTAMP(3), "notifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "removedAt" TIMESTAMP(3), CONSTRAINT "CommunityPost_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunityPost_imageAssetId_key" ON "CommunityPost"("imageAssetId");
CREATE INDEX "CommunityPost_channelId_status_publishedAt_idx" ON "CommunityPost"("channelId", "status", "publishedAt");
CREATE INDEX "CommunityPost_status_scheduledPublishAt_idx" ON "CommunityPost"("status", "scheduledPublishAt");
CREATE INDEX "CommunityPost_authorAccountId_createdAt_idx" ON "CommunityPost"("authorAccountId", "createdAt");
CREATE TABLE "CommunityPollOption" ("id" UUID NOT NULL, "postId" UUID NOT NULL, "label" VARCHAR(160) NOT NULL, "position" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CommunityPollOption_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunityPollOption_postId_position_key" ON "CommunityPollOption"("postId", "position");
CREATE TABLE "CommunityPollVote" ("id" UUID NOT NULL, "postId" UUID NOT NULL, "optionId" UUID NOT NULL, "profileId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommunityPollVote_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunityPollVote_postId_profileId_key" ON "CommunityPollVote"("postId", "profileId"); CREATE INDEX "CommunityPollVote_optionId_idx" ON "CommunityPollVote"("optionId");
CREATE TABLE "CommunityPostReaction" ("id" UUID NOT NULL, "postId" UUID NOT NULL, "profileId" UUID NOT NULL, "type" "ReactionType" NOT NULL DEFAULT 'LIKE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommunityPostReaction_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunityPostReaction_postId_profileId_key" ON "CommunityPostReaction"("postId", "profileId"); CREATE INDEX "CommunityPostReaction_postId_type_idx" ON "CommunityPostReaction"("postId", "type");
CREATE TABLE "CommunityPostComment" ("id" UUID NOT NULL, "postId" UUID NOT NULL, "authorProfileId" UUID NOT NULL, "parentId" UUID, "body" TEXT NOT NULL, "status" "CommentStatus" NOT NULL DEFAULT 'PUBLISHED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "removedAt" TIMESTAMP(3), CONSTRAINT "CommunityPostComment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CommunityPostComment_postId_status_createdAt_idx" ON "CommunityPostComment"("postId", "status", "createdAt"); CREATE INDEX "CommunityPostComment_parentId_createdAt_idx" ON "CommunityPostComment"("parentId", "createdAt");
CREATE TABLE "CommunityPostReport" ("id" UUID NOT NULL, "postId" UUID NOT NULL, "reporterProfileId" UUID NOT NULL, "reason" "ReportReason" NOT NULL, "details" TEXT, "status" "ReportStatus" NOT NULL DEFAULT 'OPEN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "resolvedAt" TIMESTAMP(3), CONSTRAINT "CommunityPostReport_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CommunityPostReport_status_createdAt_idx" ON "CommunityPostReport"("status", "createdAt"); CREATE INDEX "CommunityPostReport_postId_status_idx" ON "CommunityPostReport"("postId", "status");
ALTER TABLE "CommunityPost" ADD CONSTRAINT "CommunityPost_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommunityPost" ADD CONSTRAINT "CommunityPost_authorAccountId_fkey" FOREIGN KEY ("authorAccountId") REFERENCES "Account"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CommunityPost" ADD CONSTRAINT "CommunityPost_imageAssetId_fkey" FOREIGN KEY ("imageAssetId") REFERENCES "MediaAsset"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "CommunityPost" ADD CONSTRAINT "CommunityPost_sharedVideoId_fkey" FOREIGN KEY ("sharedVideoId") REFERENCES "Video"("id") ON DELETE SET NULL ON UPDATE CASCADE;
