ALTER TABLE "CommunityPostComment" ADD CONSTRAINT "CommunityPostComment_postId_fkey" FOREIGN KEY ("postId") REFERENCES "CommunityPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommunityPostComment" ADD CONSTRAINT "CommunityPostComment_authorProfileId_fkey" FOREIGN KEY ("authorProfileId") REFERENCES "ViewerProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CommunityPostComment" ADD CONSTRAINT "CommunityPostComment_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "CommunityPostComment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
